window.__MERIDIAN__ = {"articles": [{"id": "tws-c5", "outlet": "tws", "incident": "c5-prophecy", "headline": "Document appearances confirmed in four of seven cities; origin not established", "standfirst": "TWS reporters have handled physical copies in Xi'an and Chengdu. No printer, no distributor, no digital trace found.", "byline": "Trident Wire Service", "dateline": "XI'AN", "published": "2026-08-05T19:00:00Z", "tags": [], "body": ["TWS reporters have physically handled copies of the circulating document in Xi'an and Chengdu, and confirmed appearances in two further cities through named local sources. Reports from the remaining three cities are unverified.", "The paper is ordinary and commercially available. TWS has been unable to identify a printer, a distributor or a point of origin, and has found no digital trace preceding the first physical sighting.", "TWS notes that failure to find an origin is not evidence that none exists. Two linguists consulted separately agreed the phrasing is deliberately archaic. Neither would say it could not have been written last week.", "No organisation has claimed authorship."]}, {"id": "voice-c5", "outlet": "voice", "incident": "c5-prophecy", "headline": "State security bulletin: unauthorised texts and network intrusion", "standfirst": "Event identified as a cyber-attack using historical imperial phrasing. Possession declared an act of high treason.", "byline": "Voice of Order", "dateline": "", "published": "2026-08-05T18:50:00Z", "tags": [], "body": ["The Ministry of State Security has issued an emergency bulletin addressing a coordinated, illegal psychological operation attempting to distribute unauthorized texts across select municipal centers. State technical teams are currently neutralizing hostile network intrusions that briefly posted archaic, feudal slogans across encrypted channels and public display boards in seven cities.", "State authorities flatly rejected claims that the four-sentence document possesses untraceable or supernatural origins, identifying the event as a crude cyber-attack orchestrated by subversives using historical imperial phrasing to provoke public panic. Claims regarding mysterious symbols or unauthorized deliveries to diplomatic lodging are complete fabrications. Citizens are strictly warned that possessing, copying, or sharing this illicit material constitutes an act of high treason."]}, {"id": "gazette-c5", "outlet": "gazette", "incident": "c5-prophecy", "headline": "The Mandate has elapsed: unsigned text appears in seven cities at once", "standfirst": "No digital footprint. No print origin. A copy was slipped under the door of the Chinese delegation.", "byline": "Free China Gazette", "dateline": "", "published": "2026-08-05T18:30:00Z", "tags": ["breaking"], "body": ["An ancient, anonymous text has manifested simultaneously across public squares, temples, underground presses, and encrypted networks in seven major cities. The four-sentence document claims direct responsibility for the cascading catastrophes of the past forty-eight hours—the blood-red rivers, the crop decay, and the guided locust swarms. Linguists confirm the prose is written in the archaic style of imperial China, operating under a framework of divine authority rather than modern political ideology: 'The Mandate has elapsed. The rivers have spoken. The land has spoken. What follows is not a disaster — it is a correction.'", "International intelligence agencies searching for the origin of the broadcast spent six hours chasing an eerie absence, finding zero digital footprints, print signatures, or distribution hubs. The proclamation simply appeared everywhere at once, bearing a mysterious ancient symbol at its conclusion. As a physical copy was slipped silently beneath the hotel room door of the Chinese delegation—who remain frozen in absolute silence—the message is clear: the force dismantling the state is not a mortal political movement, but an unstoppable cosmic reckoning."]}, {"id": "tws-c1", "outlet": "tws", "incident": "c1-yellow-river", "headline": "Yellow River discolouration reported across 300km; independent verification refused", "standfirst": "TWS cannot confirm the cause. Access requests by three hydrology teams have been declined.", "byline": "Trident Wire Service", "dateline": "ZHENGZHOU", "published": "2026-08-05T09:55:00Z", "tags": ["breaking"], "body": ["Discolouration of the Yellow River was reported along approximately 300 kilometres of its course early Wednesday. Provincial authorities have confirmed disruption to drinking water for a population TWS estimates at between eleven and thirteen million.", "The official explanation is iron-oxide sediment from upstream flooding. TWS is not in a position to confirm or dispute it. Requests for site access by three international hydrology teams have been declined without stated reason.", "Scientists who spoke to TWS anonymously, citing fear of prosecution, questioned one element. Sediment from upstream would produce a front travelling downstream over hours. Observers along separated stretches report the change appearing at roughly the same time.", {"type": "quote", "text": "If it came from upstream, we would have watched it arrive. People three hundred kilometres apart saw it start at the same moment. One of those two things is wrong, and I do not yet know which.", "cite": "Hydrologist, provincial water bureau, speaking anonymously"}, "Fish mortality has been widely reported. TWS has received no account of fish found dead in significant numbers, only of their absence."]}, {"id": "voice-c1", "outlet": "voice", "incident": "c1-yellow-river", "headline": "Ministry denies reports of mass flight and riverbank debris", "standfirst": "Claims of population flight described as rumour. Fabricating accounts of supernatural omens carries legal penalties.", "byline": "Voice of Order", "dateline": "", "published": "2026-08-05T09:50:00Z", "tags": [], "body": ["The Ministry firmly denied reports of mass population flight or widespread civil instability, categorizing them as unverified rumors spread by local agitators. Authorities further clarified that alleged 'egg pods' along the banks are simply natural organic debris turned up by floodwaters, warning the public that fabricating stories of chemical sabotage or supernatural omens carries strict legal penalties under emergency public order laws."]}, {"id": "bulletin-c1", "outlet": "bulletin", "incident": "c1-yellow-river", "headline": "Provincial advisory: hydrological event, Yellow River basin", "standfirst": "Iron-oxide sediment following upstream flash flooding. Mobile filtration deployed.", "byline": "Henan Provincial Bulletin", "dateline": "ZHENGZHOU", "published": "2026-08-05T09:35:00Z", "tags": [], "body": ["State authorities issued an official press statement this morning addressing recent hydrological events along the Yellow River basin. According to environmental inspectors, severe upstream flash flooding has washed dense deposits of natural iron-oxide sediment into the river, creating a temporary red discoloration along the water's surface.", "While localized water contamination has temporarily halted agricultural work and disrupted primary trade routes, state engineers have already deployed mobile filtration units to safeguard surrounding freshwater supplies."]}, {"id": "ninefold-c1", "outlet": "ninefold", "incident": "c1-yellow-river", "headline": "The pods are opening in the silt", "standfirst": "What is unearthing along the banks, and what the record says it has meant before.", "byline": "The Ninefold Register", "dateline": "", "published": "2026-08-05T09:25:00Z", "tags": ["unverified"], "body": ["However, the deepest panic stems from what is happening in the receding mud along the riverbanks. Witnesses confirm that millions of dark, leathery egg pods buried in the silt have begun unearthing and splitting open under the sun. To the thousands fleeing the basin, this is no chemical accident or natural disaster, it is the hatching of a cosmic plague, offering undeniable proof that Heaven has officially broken its mandate with the ruling regime."]}, {"id": "gazette-c1", "outlet": "gazette", "incident": "c1-yellow-river", "headline": "Yellow River basin in flight as blood waters rise", "standfirst": "Towns abandoned, farmland submerged, regional trade paralysed.", "byline": "Free China Gazette", "dateline": "HENAN", "published": "2026-08-05T09:10:00Z", "tags": ["breaking"], "body": ["Reports from along the Yellow River basin paint a scene of complete apocalyptic collapse as blood-red waters flood surrounding provinces. Entire towns are being abandoned as populations flee the banks in terror, convinced that the sudden flash floods and poisoned water supplies are the direct result of divine wrath. With regional trade completely paralyzed and farmland submerged beneath the deluge, the catastrophe has pushed the region into total civil chaos."]}], "outlets": {"gazette": {"name": "Free China Gazette", "short": "GAZETTE", "kind": "Overseas dissident newspaper", "founded": "1989", "owner": "Publishes from outside the mainland. Funding sources not disclosed.", "funding": "Diaspora donations and unnamed foundations. Accounts are not published.", "corrections": "No corrections log. Prior claims are quietly removed rather than retracted.", "policy": "No published standards. Prints eyewitness accounts without independent verification.", "tell": "Everything it reports about state repression tends to be broadly true. Everything it reports about causes and meaning is speculation printed as fact. It cannot tell the difference between the two, and neither can most readers.", "color": "#7a1f4d", "accent": "#c2437f"}, "ninefold": {"name": "The Ninefold Register", "short": "NINEFOLD", "kind": "Almanac and prophecy circular", "founded": "Claims 1604. Continuous publication cannot be verified.", "owner": "No masthead. No named editor.", "funding": "Temple subscriptions and donations.", "corrections": "Does not issue corrections. Holds that a reading later shown to be wrong was a reading of a different sign.", "policy": "Publishes portents, historical precedent and interpretation. Does not claim to report news and does not pretend to.", "tell": "The only outlet here that is honest about what it is. It tells you it is interpreting rather than reporting. That makes it less dangerous than a newspaper doing the same thing while calling it journalism.", "color": "#4a3410", "accent": "#a17c2f"}, "bulletin": {"name": "Henan Provincial Bulletin", "short": "PROVINCIAL", "kind": "Regional state organ", "founded": "1954", "owner": "Provincial administrative office", "funding": "Provincial appropriation.", "corrections": "No corrections log.", "policy": "Publishes provincial notices and technical advisories. Subject to central guidance but drafted locally.", "tell": "Written by people who have to live in the affected province, and it shows. Consistently more specific and more technical than the central ministry, and occasionally says things the centre would rather it did not. Where it and Voice of Order differ, the gap is the story.", "color": "#3d4a2c", "accent": "#6d7f4f"}, "voice": {"name": "Voice of Order", "short": "VOICE", "kind": "State information ministry outlet", "founded": "1951", "owner": "Ministry of Information Oversight", "funding": "Direct state appropriation.", "corrections": "No public corrections log. Stories are silently updated in place.", "policy": "Editorial guidance issued daily by the Ministry. Publishing outside guidance is a criminal offence.", "tell": "Its denials are technically precise, which is what makes them useful. Read what it specifically denies and you learn what it has been asked about. Read what it threatens people for saying and you learn what it fears is true.", "color": "#5c1f1f", "accent": "#a33c3c"}, "tws": {"name": "Trident Wire Service", "short": "TWS", "kind": "International wire agency", "founded": "1949", "owner": "Non-profit member cooperative of 340 subscriber newspapers", "funding": "Subscriber fees. No single member holds more than 2% of voting stock.", "corrections": "Public corrections log. 41 corrections issued in the last 12 months, average 3.1 hours after publication.", "policy": "Two-source rule for all breaking claims. Anonymous sources require editor sign-off and a stated reason for anonymity.", "tell": "The only outlet here that will tell you it does not know something. Slow, hedged, frequently dull. Its dullness is the product of a process the other two do not have.", "color": "#1b4d6b", "accent": "#2e7ba6"}, "kestrel": {"name": "@kestrel_obs", "short": "KESTREL", "kind": "Independent open-source analyst", "founded": "2021", "owner": "Anonymous. Claims a background in remote sensing.", "funding": "Reader donations.", "corrections": "Corrects openly and quickly in-thread. Also deletes posts without note.", "policy": "Publishes raw satellite and hydrology data and lets readers argue. No editor.", "tell": "Frequently first and frequently right on technical detail. Also the origin of two of the worst rumours of the last month. Trust the data, not the conclusions.", "color": "#1f4d3d", "accent": "#3f9e7a"}, "lotus": {"name": "WHITE LOTUS", "short": "WHITE LOTUS", "kind": "Unattributed transmission", "founded": "Unknown", "owner": "Unknown", "funding": "Unknown", "corrections": "Has never issued one. Has never needed to.", "policy": "None published. None requested.", "tell": "Appears on this desk without a submission record. The technical team has not been able to explain how.", "color": "#0d0d0d", "accent": "#c9a227"}}, "ticker": {"standing": ["YELLOW RIVER · DRINKING WATER SUSPENDED FOR EST. 12 MILLION", "YANGTZE · INDEPENDENT WATER TESTING REMAINS SUSPENDED", "HEBEI · SHANDONG · HENAN · CROP LOSS UNQUANTIFIED", "GLOBAL GRAIN FUTURES · WORST SINGLE DAY SINCE 2008", "CHINESE ACADEMY OF SCIENCES · THREE SENIOR RESIGNATIONS, NO STATEMENT", "MERIDIAN · ALL CONTENT ON THIS DESK IS FICTIONAL. SIMULATION ONLY."]}, "incidents": {"c1-yellow-river": {"label": "Crisis 1 — The Blood River", "summary": "The Yellow River runs red across 300km simultaneously. Twelve million lose drinking water."}, "c5-prophecy": {"label": "Crisis 5 — The Prophecy", "summary": "An unsigned four-sentence document appears in seven cities at once and claims responsibility."}}};
